import math


def _div_trunc(a: int, b: int) -> int:
    if b == 0:
        raise ValueError("division by zero")
    q = abs(a) // abs(b)
    return -q if (a < 0) ^ (b < 0) else q


def _mod_trunc(a: int, b: int) -> int:
    if b == 0:
        raise ValueError("modulo by zero")
    return a - _div_trunc(a, b) * b


def evaluate(expr: str) -> int:
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")

    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif "0" <= ch <= "9":
            j = i + 1
            while j < n and "0" <= expr[j] <= "9":
                j += 1
            tokens.append(("NUM", int(expr[i:j])))
            i = j
        elif ch in "+-*/%^!()":
            tokens.append((ch, ch))
            i += 1
        else:
            raise ValueError(f"unexpected character: {ch!r}")
    tokens.append(("EOF", None))

    pos = 0

    def peek() -> str:
        return tokens[pos][0]

    def consume(expected: str | None = None):
        nonlocal pos
        tok = tokens[pos]
        if expected is not None and tok[0] != expected:
            raise ValueError(f"expected {expected}, got {tok[0]}")
        pos += 1
        return tok

    def parse_add() -> int:
        val = parse_mul()
        while peek() in ("+", "-"):
            op = consume()[0]
            rhs = parse_mul()
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    def parse_mul() -> int:
        val = parse_unary()
        while True:
            tok = peek()
            if tok in ("*", "/", "%"):
                consume()
                rhs = parse_unary()
                if tok == "*":
                    val *= rhs
                elif tok == "/":
                    val = _div_trunc(val, rhs)
                else:
                    val = _mod_trunc(val, rhs)
            elif tok == "(":
                val *= parse_unary()
            else:
                break
        return val

    def parse_unary() -> int:
        neg = False
        while peek() == "-":
            consume()
            neg = not neg
        val = parse_power()
        return -val if neg else val

    def parse_power() -> int:
        base = parse_postfix()
        if peek() == "^":
            consume()
            exp = parse_unary()
            if exp < 0:
                raise ValueError("negative exponent")
            return base ** exp
        return base

    def parse_postfix() -> int:
        val = parse_primary()
        while peek() == "!":
            consume()
            if val < 0:
                raise ValueError("factorial of negative number")
            val = math.factorial(val)
        return val

    def parse_primary() -> int:
        tok = peek()
        if tok == "NUM":
            return consume()[1]
        if tok == "(":
            consume("(")
            val = parse_add()
            consume(")")
            return val
        raise ValueError(f"unexpected token: {tok}")

    if peek() == "EOF":
        raise ValueError("empty expression")
    result = parse_add()
    if peek() != "EOF":
        raise ValueError(f"unexpected trailing token: {peek()}")
    return result
